__d(function(g,r,i,_a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"LESSONS",{enumerable:!0,get:function(){return t}}),e.nextLesson=function(o){const n=o.areas??[],s=s=>{const l=t.find(t=>t.n===s);return!!l&&a(l,n,o.labels??[])},l=[];o.painUp&&l.push(4);l.push(...t.filter(t=>t.dx).map(t=>t.n),...t.filter(t=>t.areas).map(t=>t.n)),o.mind.includes('worry')&&l.push(1,3);o.mind.includes('avoid')&&l.push(5,7);(o.mind.includes('sleep')||o.mind.includes('down'))&&l.push(6,15);return l.push(...o.phase>=3?[8,7,5,12]:2===o.phase?[5,7,12,1,2]:[1,2,4],...t.map(t=>t.n)),l.find(t=>s(t)&&!o.seen.includes(t))??null},Object.defineProperty(e,"lessonFits",{enumerable:!0,get:function(){return o}});const t=[{n:1,title:"Hurt doesn't always mean harm",body:"Pain is your body's alarm system, and alarms can be sensitive. Feeling some pain during exercise usually means the system is protective, not that you're doing damage. Our rule: pain during exercise up to 3 out of 10 is fine, as long as you're back to normal by the next morning."},{n:2,title:"Pain has a volume knob",body:"Your nervous system decides how loud pain is, based on more than the tissue. Stress, poor sleep, worry and past flares can turn it up. The good news: movement, sleep, confidence and time turn it back down. That's what your plan is built to do."},{n:3,title:"Scans find things in people with no pain",body:"Disc bulges, rotator cuff tears and arthritis show up on plenty of scans of people who feel fine, and they get more common with age, like gray hair. A finding on a scan doesn't mean it's the cause of your pain, and it doesn't mean you can't get better."},{n:4,title:"Flare plan: ease off, don't stop",body:"Flares happen and they usually settle in a few days. Cut your exercise back by about half, keep moving gently, and get your sleep. Don't rest it completely. If it's not settling after a week, or something new shows up, tell me in your check in."},{n:5,title:"Motion is lotion",body:"Joints, discs and tendons get their nutrition from movement, and resting too long makes everything more sensitive. Gentle movement is one of the fastest ways to calm pain down. Your Calm it moves are picked to feel good, not to push through."},{n:6,title:"Sleep and stress change pain",body:"One bad night can make pain feel worse the next day, and steady stress keeps the volume knob turned up. Protect your sleep: same bedtime, a dark cool room, screens off an hour before. A short walk or slow breathing helps on stressful days."},{n:7,title:"Pace by plan, not by feel",body:"On good days it's tempting to do too much, then pay for it. Instead, set an amount you can do on a bad day and grow it a little each week, about 10 percent. Steady beats heroic, and it's how you build capacity without flares."},{n:8,title:"Setbacks are part of the road",body:"Recovery isn't a straight line. A bad week after a few good ones is normal and doesn't erase your progress. Look at the trend over a month, not the day. You now know how to handle a flare, and that's what keeps you in control long term."},{n:9,title:"Disc changes are normal with age",body:"In people with no back pain at all, about a third of 20 year olds show disc degeneration on a scan, and nearly everyone does by 80. These changes are closer to wrinkles on the inside than to an injury.",areas:["Low back","Mid back","Neck"],source:"Brinjikji et al. 2015, American Journal of Neuroradiology"},{n:10,title:"Herniated discs often shrink on their own",body:"A disc herniation is not permanent for most people. In a review of studies that scanned people again later, the biggest herniations shrank the most often: 96 percent of the largest type and 70 percent of the next largest got smaller without surgery.",areas:["Low back"],source:"Chiu et al. 2015, Clinical Rehabilitation"},{n:11,title:"Meniscus tears show up in knees that feel fine",body:"In a large study of middle aged and older adults, 61 percent of the people who had a meniscus tear on their scan had no knee pain, aching or stiffness. A tear on a report is not always the reason a knee hurts.",areas:["Knee"],source:"Englund et al. 2008, New England Journal of Medicine"},{n:12,title:"Strength training lowers injury risk",body:"Across 25 trials in athletes, strength training cut sports injuries to less than a third, and overuse injuries were almost halved. Stretching alone showed no benefit. Getting stronger is one of the best protections there is.",source:"Lauersen et al. 2014, British Journal of Sports Medicine"},{n:13,title:"Walking helps keep back pain away",body:"In a trial of adults who had just recovered from back pain, a walking and education program meant a typical wait of 208 days before the next episode, compared with 112 days without it.",areas:["Low back"],source:"Pocovi et al. 2024, The Lancet"},{n:14,title:"Running doesn't wear out your knees",body:"In a review covering about 115,000 people, 3.5 percent of recreational runners had hip or knee arthritis, compared with 10.2 percent of people who didn't run. Joints adapt to the load you give them.",areas:["Knee","Hip"],source:"Alentorn-Geli et al. 2017, Journal of Orthopaedic and Sports Physical Therapy"},{n:15,title:"Short sleep raises injury risk",body:"In a study of teenage athletes, those who slept less than 8 hours a night were 1.7 times more likely to get injured than those who slept 8 or more. Sleep is when your body does its repair work.",source:"Milewski et al. 2014, Journal of Pediatric Orthopaedics"},{n:16,title:"Pain is a protector, not a damage meter",body:"Pain is your nervous system's way of protecting you. It turns up when your body senses threat, and that doesn't always match how much tissue damage there is. A paper cut hurts a lot. A big bruise can show up with no memory of the hit.",source:"Louw et al. 2016, Physiotherapy Theory and Practice"},{n:17,title:"Your back is built strong",body:"Your spine is one of the sturdiest structures in your body. It's made to bend, twist and carry load. Back pain is common and rarely means something is seriously wrong. Moving it, loading it and trusting it again is usually the way forward.",areas:["Low back","Mid back"],source:"O'Sullivan et al. 2020, British Journal of Sports Medicine"},{n:18,title:"Rotator cuff tears get more common with age",body:"Rotator cuff changes become more common with every decade, and many people who have one never notice it. Shoulders can work well and feel good with a tear, which is why strength and movement come first.",areas:["Shoulder"],source:"Teunis et al. 2014, Journal of Shoulder and Elbow Surgery"},{n:19,title:"Cracking your knuckles is fine",body:"The pop is gas moving inside the joint, not bone on bone. A study comparing people who crack their knuckles with people who don't found no link to hand arthritis.",source:"deWeber et al. 2011, Journal of the American Board of Family Medicine"},{n:20,title:"Some pain during exercise is okay",body:"Exercise doesn't have to be pain free to help. In a review of trials on long lasting muscle and joint pain, programs that allowed some pain did slightly better in the short term than pain free ones, and the same after that. That's why your plan uses a pain limit, not a pain ban.",source:"Smith et al. 2017, British Journal of Sports Medicine"},{n:21,title:"Stretching doesn't prevent soreness",body:"Stretching before or after a workout makes almost no difference to how sore you feel the next day. Soreness after new exercise is normal and fades in a few days as your body adapts.",source:"Herbert et al. 2011, Cochrane Database of Systematic Reviews"},{n:22,title:"Tendons like load, not rest",body:"Tendons need load to recover. In a trial of Achilles tendon pain, people who kept up their sport within a pain limit improved just as much as those who rested from it, with no harm from the extra loading.",areas:["Tendon"],source:"Silbernagel et al. 2007, American Journal of Sports Medicine"},{n:23,title:"There is no one perfect posture",body:"Research has not found a single correct way to sit or stand that prevents pain. Comfortable, relaxed positions are fine. What helps most is changing position often. Your best posture is your next one.",areas:["Low back","Mid back","Neck"],source:"Slater et al. 2019, Journal of Orthopaedic and Sports Physical Therapy"},{n:24,title:"A rounded back when lifting isn't the enemy",body:"A review of the research found that bending your back when you lift was not a risk factor for back pain. Build up to heavy lifts a little at a time.",areas:["Low back"],source:"Saraceni et al. 2020, Journal of Orthopaedic and Sports Physical Therapy"},{n:25,title:"Staying active beats bed rest",body:"For a fresh episode of back pain, people advised to stay active did a little better on pain and function than people told to rest in bed. Short rests are fine. Days in bed tend to slow things down.",areas:["Low back"],source:"Dahm et al. 2010, Cochrane Database of Systematic Reviews"},{n:26,title:"A real warm up is worth it",body:"In soccer players, a structured warm up of running, strength and balance drills led to about 39 percent fewer injuries across four trials. Ten minutes of the right prep pays off.",source:"Thorborg et al. 2017, British Journal of Sports Medicine"},{n:27,title:"Surgery did no better than a placebo operation",body:"In a trial of 313 people with pain at the top of the shoulder, shaving the bone to make more room did no better than a placebo operation. That's why loading and strengthening the shoulder comes first.",areas:["Shoulder"],dx:"rotator cuff tendinopathy|subacromial",source:"Beard et al. 2018, The Lancet"},{n:28,title:"Strength work helps neck pain, stretching alone doesn't",body:"A review of trials found that strengthening the neck, shoulder blades and arms eased long lasting neck pain. Stretching alone did not. That's why your plan builds strength.",areas:["Neck"],source:"Gross et al. 2015, Cochrane Database of Systematic Reviews"},{n:29,title:"Exercise eases hip arthritis pain",body:"In a review of 10 trials, exercise lowered hip arthritis pain by about 8 points out of 100 and improved function by about 7. The gains were still there three to six months after the program ended.",areas:["Hip"],dx:"hip osteoarthritis",source:"Cochrane review of exercise for hip osteoarthritis, 2026 update"},{n:30,title:"Exercise is a proven treatment for knee arthritis",body:"Across 44 trials and more than 3,500 people, exercise gave a moderate drop in knee arthritis pain and a moderate gain in what people could do. Arthritis on a scan doesn't mean your knee can't get stronger.",areas:["Knee"],dx:"knee osteoarthritis",source:"Fransen et al. 2015, Cochrane Database of Systematic Reviews"},{n:31,title:"Meniscus surgery did no better than a placebo operation",body:"In a trial of 146 people with a wear and tear meniscus tear and no arthritis, trimming the meniscus did no better than a placebo operation after 12 months. A tear from a sudden injury, or a knee that locks, is a different situation, so ask me about yours.",areas:["Knee"],dx:"degenerative meniscus",source:"Sihvonen et al. 2013, New England Journal of Medicine"},{n:32,title:"The quick fix for tennis elbow can come back",body:"In a trial of 165 people with tennis elbow, 54 percent of those given a steroid injection had it come back within a year, compared with 12 percent given a placebo injection. Building the tendon back up takes patience.",areas:["Elbow"],dx:"tennis elbow|lateral elbow tend",source:"Coombes et al. 2013, JAMA"},{n:33,title:"Heel raises work faster than stretching",body:"In a trial of 48 people with plantar fasciitis, slow heavy heel raises gave much better results at 3 months than stretching. By 12 months the two groups were even, so strength work gets you there sooner.",areas:["Ankle or foot"],dx:"plantar fasci",source:"Rathleff et al. 2015, Scandinavian Journal of Medicine and Science in Sports"},{n:34,title:"Exercise beat an injection for gluteal tendon pain",body:"In a trial of 204 people with gluteal tendon pain, 79 percent of those who did education and exercise rated themselves better a year later, compared with 58 percent after a steroid injection and 52 percent of those who waited.",areas:["Hip"],dx:"gluteal tendinopathy",source:"Mellor et al. 2018, BMJ"},{n:35,title:"Rehab first is a real option after an ACL tear",body:"In a trial of 121 active young adults with a fresh ACL tear, everyone did rehab and half had surgery early. In the other half, 61 percent had not needed surgery two years later, and knee scores were the same in both groups. Surgery is still the right call for some knees, so that's a decision for you, me and your surgeon.",areas:["Knee"],dx:"ACL",source:"Frobell et al. 2010, New England Journal of Medicine"},{n:36,title:"Sciatica from a disc usually recovers",body:"In a trial of 283 people with sciatica from a disc, early surgery eased leg pain faster. After a year, 95 percent had recovered in both groups, whether they had surgery early or waited and had it only if needed.",areas:["Low back"],dx:"radiculopathy|radiating|sciatic",source:"Peul et al. 2007, New England Journal of Medicine"},{n:37,title:"Neck scans show bulges in necks that feel fine",body:"In a study of 1,211 people with no neck symptoms, about 88 percent had a bulging disc on their neck scan. Findings like that are common in necks that feel fine.",areas:["Neck"],source:"Nakashima et al. 2015, Spine"},{n:38,title:"Rehab lowers the odds of spraining it again",body:"A review of the research found that rehab exercise lowered the odds of spraining the same ankle again by about 40 percent, and a brace or tape lowered them further. Finishing your balance and strength work is what protects it.",areas:["Ankle or foot"],dx:"^ankle sprain|chronic ankle instability",source:"Doherty et al. 2017, British Journal of Sports Medicine"},{n:39,title:"Hip strength helps kneecap pain",body:"A review of trials found that exercise eases kneecap pain and improves what people can do, and that adding hip exercises to knee exercises may ease pain a little more.",areas:["Knee"],dx:"patellofemoral",source:"van der Heijden et al. 2015, Cochrane Database of Systematic Reviews"}],a=(t,a,o)=>(!t.areas||t.areas.some(t=>a.includes(t)))&&(!t.dx||o.some(a=>new RegExp(t.dx,'i').test(a)));const o=(o,n,s=[])=>{const l=t.find(t=>t.n===o);return!!l&&a(l,n,s)}},842,[]);
